<?php use App\Core\Csrf; use App\Core\View; ?>
<div class="page-head"><div><h1>考核考试</h1><p>从考核题库手工选题或按题型随机抽题，发布时生成不可变快照。</p></div></div>
<details class="card" open><summary>创建考试草稿</summary><div><form method="post" action="/admin/exams"><?= Csrf::field() ?><div class="form-grid"><div class="field"><label>考试名称</label><input name="title" required maxlength="180"></div><div class="field"><label>组卷方式</label><select name="compose_mode" data-toggle-target="#random-rules" data-toggle-value="random"><option value="manual">手工选题</option><option value="random">随机抽题</option></select></div><div class="field full"><label>考试说明</label><textarea name="description"></textarea></div><div class="field"><label>开放时间</label><input type="datetime-local" name="opens_at"></div><div class="field"><label>截止时间</label><input type="datetime-local" name="closes_at"></div><div class="field"><label>限时（分钟，0 表示不限时）</label><input type="number" min="0" name="duration_minutes" value="0"></div><div class="field"><label>参考答案展示</label><select name="answer_release"><option value="after_close">统一结束后</option><option value="immediate">个人提交后立即</option><option value="manual">管理员手动发布</option></select></div><div class="field"><label>成绩展示</label><select name="result_release"><option value="manual">管理员手动发布</option><option value="after_graded">评分后自动（预留）</option></select></div>
<div class="field full"><label>手工选择题目</label><div class="table-wrap"><table><thead><tr><th>选择</th><th>题目</th><th>类型</th><th>分值</th></tr></thead><tbody><?php foreach($questions as$q):?><tr><td><input type="checkbox" name="question_ids[]" value="<?= $q['id'] ?>"></td><td><?= View::e($q['title']) ?></td><td><?= $q['question_type']==='practical'?'实践':'主观' ?></td><td><?= View::e($q['default_score']) ?></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="full grid grid-4" id="random-rules"><div class="field"><label>主观题数量</label><input type="number" min="0" name="subjective_count" value="5"></div><div class="field"><label>实践题数量</label><input type="number" min="0" name="practical_count" value="0"></div><div class="field"><label>难度</label><select name="difficulty"><option value="all">全部</option><option value="easy">简单</option><option value="medium">中等</option><option value="hard">困难</option></select></div><div class="field"><label>标签包含</label><input name="tags_filter"></div></div></div><div class="toolbar top-gap"><button class="btn btn-primary">保存草稿</button></div></form></div></details>
<section class="card"><h2 class="section-title">考试列表</h2><div class="table-wrap"><table><thead><tr><th>考试</th><th>状态</th><th>题量</th><th>学生/提交</th><th>时间</th><th>操作</th></tr></thead><tbody><?php foreach($exams as$e):?><tr><td><strong><?= View::e($e['title']) ?></strong><br><span class="muted"><?= $e['compose_mode']==='random'?'随机组卷':'手工组卷' ?></span></td><td><span class="status status-<?= View::e($e['status']) ?>"><?= View::e($e['status']) ?></span></td><td><?= (int)$e['question_count'] ?></td><td><?= (int)$e['student_count'] ?> / <?= (int)$e['submitted_count'] ?></td><td><?= View::e($e['opens_at']??'不限') ?><br><?= View::e($e['closes_at']??'不限') ?></td><td><div class="toolbar"><?php if($e['status']==='draft'):?><form method="post" action="/admin/exams/<?= $e['id'] ?>/publish" data-confirm="发布后题目形成快照并分配给全部有效学生，确定发布？"><?= Csrf::field() ?><button class="btn btn-sm btn-primary">发布</button></form><?php else:?><form method="post" action="/admin/exams/<?= $e['id'] ?>/release"><?= Csrf::field() ?><input type="hidden" name="release" value="answers"><button class="btn btn-sm">发布答案</button></form><form method="post" action="/admin/exams/<?= $e['id'] ?>/release"><?= Csrf::field() ?><input type="hidden" name="release" value="results"><button class="btn btn-sm btn-success">发布成绩</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>

